package com.multicall.audio;
import android.app.*; import android.os.*; import android.content.*; import android.media.*; import android.widget.*; import android.view.*; import rikka.shizuku.Shizuku;
public class MainActivity extends Activity {
 LinearLayout panel; TextView status; AudioManager audio;
 void heading(String s){TextView t=new TextView(this);t.setText(s);t.setTextSize(22);panel.addView(t);}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);panel.addView(b);b.setOnClickListener(v->r.run());}
 void launch(String p){Intent i=getPackageManager().getLaunchIntentForPackage(p);if(i!=null)startActivity(i);else status.setText("App not installed or not visible: "+p);}
 void volume(String label,int stream){TextView t=new TextView(this);t.setText(label);panel.addView(t);SeekBar s=new SeekBar(this);s.setMax(audio.getStreamMaxVolume(stream));s.setProgress(audio.getStreamVolume(stream));panel.addView(s);s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){} public void onStopTrackingTouch(SeekBar b){} public void onProgressChanged(SeekBar b,int p,boolean user){if(user)try{audio.setStreamVolume(stream,p,0);}catch(Exception e){status.setText(e.toString());}}});}
 @Override public void onCreate(Bundle b){super.onCreate(b);audio=(AudioManager)getSystemService(AUDIO_SERVICE);ScrollView scroll=new ScrollView(this);panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(32,32,32,32);scroll.addView(panel);setContentView(scroll);heading("MultiCall Audio");status=new TextView(this);panel.addView(status);status.setText("Audio controls • Samsung + Shizuku");heading("Meeting mode");volume("Media volume",AudioManager.STREAM_MUSIC);volume("Call stream volume (app dependent)",AudioManager.STREAM_VOICE_CALL);button("Open Samsung Sound Assistant / Multi Sound",()->launch("com.samsung.android.soundassistant"));button("Open Teams",()->launch("com.microsoft.teams"));button("Open Zoom",()->launch("us.zoom.videomeetings"));button("Open Meet",()->launch("com.google.android.apps.meetings"));heading("Silent Duolingo");button("Connect Shizuku",()->{try{if(!Shizuku.pingBinder()){status.setText("Start Shizuku first.");return;}if(Shizuku.checkSelfPermission()!=0)Shizuku.requestPermission(1);else status.setText("Shizuku permission granted.");}catch(Exception e){status.setText(e.toString());}});button("Block Duolingo audio focus",()->op("ignore"));button("Restore Duolingo audio focus",()->op("default"));button("Check Duolingo focus setting",()->op("get"));button("Open Duolingo",()->launch("com.duolingo"));heading("Diagnostics");button("Check audio mode",()->status.setText("Audio mode: "+audio.getMode()+"; communication mode: "+(audio.getMode()==AudioManager.MODE_IN_COMMUNICATION))); }
 void op(String mode){new Thread(()->{String result;try{if(!Shizuku.pingBinder()||Shizuku.checkSelfPermission()!=0)throw new Exception("Connect and authorize Shizuku first.");java.lang.reflect.Method m=Shizuku.class.getDeclaredMethod("newProcess",String[].class,String[].class,String.class);m.setAccessible(true);String[] cmd=mode.equals("get")?new String[]{"cmd","appops","get","com.duolingo","TAKE_AUDIO_FOCUS"}:new String[]{"cmd","appops","set","com.duolingo","TAKE_AUDIO_FOCUS",mode};java.lang.Process p=(java.lang.Process)m.invoke(null,cmd,null,null);String out=new String(p.getInputStream().readAllBytes());String err=new String(p.getErrorStream().readAllBytes());int code=p.waitFor();result="Exit "+code+" "+out+" "+err+(code==0?" — test Spotify and Duolingo to verify behavior.":"");}catch(Exception e){result="Unavailable: "+e+"; use Samsung Multi Sound as fallback.";}String r=result;runOnUiThread(()->status.setText(r));}).start();}
}